import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int totalNumbers = input.nextInt();
        int btcFunds = input.nextInt();
        int[] btcDiffs = new int[100];
        int evenCount = 0, oddCount = 0;
        int buffer = 0;
        for (int i = 0; i < totalNumbers; i++) {
            int currentNumber = 0;
            if (buffer == 0) {
                currentNumber = input.nextInt();
            } else {
                currentNumber = buffer;
                buffer = 0;
            }
            if (currentNumber % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            if (evenCount == oddCount && i != totalNumbers - 1) {
                buffer = input.nextInt();
                int diff = Math.abs(currentNumber - buffer);
                btcDiffs[diff] += 1;
                evenCount = 0;
                oddCount = 0;
            }
        }
        int totalSawnCount = 0;
        int totalCost = 0;
        for (int i = 0; i < 100; i++) {
            for (int j = 0; j < btcDiffs[i]; j++) {
                totalCost += i;
                if (totalCost <= btcFunds) {
                    totalSawnCount++;
                } else {
                    break;
                }
            }
        }
        System.out.println(totalSawnCount);
    }
}
