#include <iostream>
#include <vector>
#include <cmath>

int main() {
    int totalNumbers, btcFunds;
    std::cin >> totalNumbers >> btcFunds;
    std::vector<int> btcDiffs(100, 0);
    int evenCount = 0, oddCount = 0;
    int buffer = 0;
    for (int i = 0; i < totalNumbers; i++) {
        int currentNumber = 0;
        if (buffer == 0) {
            std::cin >> currentNumber;
        } else {
            currentNumber = buffer;
            buffer = 0;
        }
        if (currentNumber % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }
        if (evenCount == oddCount && i != totalNumbers - 1) {
            std::cin >> buffer;
            int diff = std::abs(currentNumber - buffer);
            if (diff < 100) {
                btcDiffs[diff] += 1;
            }
            evenCount = 0;
            oddCount = 0;
        }
    }
    int totalSawnCount = 0;
    int totalCost = 0;
    for (int i = 0; i < 100; i++) {
        for (int j = 0; j < btcDiffs[i]; j++) {
            totalCost += i;
            if (totalCost <= btcFunds) {
                totalSawnCount++;
            } else {
                break;
            }
        }
        if (totalCost > btcFunds) {
            break;
        }
    }
    std::cout << totalSawnCount << std::endl;
    return 0;
}
